import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第二卷 回潮 · 第31章 县城一日","description":"","frontmatter":{},"headers":[],"relativePath":"第31章_县城一日.md","filePath":"第31章_县城一日.md"}'),r={name:"第31章_县城一日.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第二卷-回潮-·-第31章-县城一日" tabindex="-1">第二卷 回潮 · 第31章 县城一日 <a class="header-anchor" href="#第二卷-回潮-·-第31章-县城一日" aria-label="Permalink to &quot;第二卷 回潮 · 第31章 县城一日&quot;">​</a></h1><p>那年春天开学后第一个能喘气的休息日，江苒在纸条上写，县城，去不去。</p><p>先把话说在前头，那天弄丢的只是普发的那罐纸星瓶，真正的许愿瓶一直揣在我口袋里。</p><p>她把纸条折得很小，塞进我手心的时候还带着温度。铃铛在她手腕上轻轻响了一下，声音脆，像是被风碰了一下。</p><p>我点头。她立刻笑了，眼睛弯起来，亮得让我不敢多看。</p><p>去县城要坐很久的车。车窗开了一道缝，风灌进来，带着青草的味道。江苒靠着窗，看外面。经过河的时候，她忽然指了一下，说你看，水亮了。</p><p>我顺着看过去。河面很宽，阳光落在上面，一闪一闪的。远处有白鹭掠过去，只能看见一道白影。</p><p>林小满坐在我们前一排，回头冲我们做鬼脸。她说，我打听好了，河边有人下象棋，还有小店卖橘子味的汽水。</p><p>顾远抱着胳膊在旁边闭目养神，听见汽水两个字才睁开眼，说那还等什么，下车就去。</p><p>县城的河边和镇上不一样。路更宽，柳枝垂下来，风一吹就晃。空气里有水的腥气，也混着吃食的香味。</p><p>我们沿着河慢慢走。江苒走在最前面，步子轻，时不时停下来捡一块好看的石头。她捡起一块扁扁的，问我，会打水漂吗。</p><p>我说会一点。</p><p>她把石头递给我，指尖有点凉。我侧身扔出去，石头在水上跳了几下，沉了。她拍手，铃铛跟着响，笑声顺着风跑出去很远。</p><p>林小满说，看我的。她也捡了一块，用力扔出去，一下就沉了。她自己先愣住，然后哈哈大笑起来。</p><p>顾远摇头，说还是看我的。他挑了半天，扔出去，石头跳了两下。他一脸得意，冲陈默抬下巴。</p><p>陈默走在最后，手里拿着本书。他看了我们一眼，嘴角动了动。他说，风太大，不适合比这个。</p><p>我们走到一处背风的地方，那里围了一圈人，中间摆着象棋摊。几个老人坐着看，神情专注。有个穿深色外衣的阿伯捏着棋子，半天不落，眉头皱着。</p><p>江苒好奇，挤进去看。她看不懂，却看得很认真，还小声问我，那个是什么字。</p><p>我说，是马。她点头，哦了一声，又问，那走哪里算赢。</p><p>我说，把对方的将困住就算赢。</p><p>她似懂非懂地点头，又看了一会，忽然说，我觉得红色的好看。</p><p>旁边看棋的阿伯听见了，笑起来，说小姑娘说得对，红色好看，红色要赢了。</p><p>大家都笑了。江苒有点不好意思，耳朵红了，往我身后躲了躲。她的衣角碰到我的手背，软软的。风掠过河面带来凉意，舌尖还留着早上含过的薄荷糖的薄凉，耳边棋子轻敲木盘的脆响混着远处汽水开盖的气泡声，一凉一脆，让人心里也跟着静下来。</p><p>林小满倒是自来熟，很快和旁边卖瓜子的宋阿婆聊上了。宋阿婆把瓜子塞给林小满，说吃吧，不收钱。</p><p>林小满摆手说不行，一边说一边已经剥了一颗放进嘴里。她眼睛亮了，说好香啊。</p><p>宋阿婆说，看了半辈子了，看不腻。她指了指河面，说年轻的时候，也有人在这里教她认棋子，可惜那人后来去了远方。</p><p>林小满听得入神，瓜子都忘了嗑。她后来跟我们学这段的时候，眼睛里有光。她说你们不觉得吗，阿婆说起那个人，语气一点都不苦，就像在说今天的风很软。</p><p>我在旁边听着，心里动了一下。水声轻轻的，一下一下。</p><p>中午太阳晒起来，我们去找小店。林小满带路，左拐右拐，找到一家门很小的店。门口挂着布帘，上面印着橘子图案，颜色被晒得发白。</p><p>我先把她的书包接过来拎在手里，把她掉在地上的石头捡起递回，又把自己喝空的水杯盖拧紧，往侧袋里塞正。走到店门口又把布帘用手背托起，等她先钻进去，自己才跟着低头进去，帘子在身后轻轻晃回去，带起一阵橘子香。</p><p>店里凉快，有薄荷的味道。老板姐姐问我们喝什么。林小满大声说，橘子味的汽水，要冰的。</p><p>汽水拿上来，瓶身凉凉的，贴着手心很舒服。瓶盖打开，气泡涌上来。江苒喝了一口，眼睛眯起来，说好喝。</p><p>我也喝了一口。甜中带酸，气泡在舌尖炸开，凉到心里。瓶外凝了一层水珠，滴在木桌上。</p><p>顾远一口气喝了半瓶，打了个嗝，自己先笑了。陈默喝得很慢，喝完把瓶子摆整齐，看标签上的小字。</p><p>林小满喝到一半，忽然想起什么，跑去跟老板姐姐说话。她说姐姐你这里能留联系方式吗，我们以后还想来。她说得坦荡，一点也不扭捏。</p><p>老板姐姐笑了，拿出本子，说写在这里吧。她说，你们是南雾中学的吧，以前也有学生来留纸条。</p><p>我们互相看看。江苒眼睛亮了，拿出纸笔，写了几句能找到我们的短句，又画了一颗小星星，压在瓶子下面。</p><p>姐姐把本子收好，说好，下次来，我还给你们留薄荷水喝。她说话时，风吹动门口的布帘，橘子图案晃了一下。</p><p>从店里出来，光已经斜了。河面上的光变成暖暖的金色。我们顺着来时的路往回走。</p><p>江苒把剩下的汽水举起来，对着太阳看，说你看，颜色像晚霞。她把瓶子递给我。我透过玻璃看她，觉得她的脸也被染成了暖色。</p><p>林小满走在前面，忽然回头说，哎，你们有没有觉得，今天像是从水里捞出来的一天，凉凉的，又亮亮的。</p><p>顾远说，你这是什么形容。林小满说，就是感觉嘛。陈默轻声说，挺贴切的。林小满立刻得意起来，看吧，还是陈默懂我。</p><p>江苒这时轻轻碰了碰我的袖口，半开玩笑地说：“你别光看河，也看看我呀。”这话没牵出新事，只是把走路的风都说暖了，我一时没答上，只把汽水瓶往她那边递了递。</p><p>风大了些，带来饭菜的香气，还有河水的湿气。江苒把手缩进袖子里，只露出指尖，铃铛偶尔响一下。想起去年在操场边她也是这样缩着手看我打水漂，那时我扔得更差，她却笑得更响，这会儿想起来，手心里也跟着暖了一下。</p><p>走到车站的时候，天边已经有了薄薄的暮色。江苒忽然停住，翻自己的小包，翻了半天，抬头看我，眼神有点慌。</p><p>她说，我的纸星星瓶子呢，会不会落在小店了。</p><p>我帮她一起找，包里只有书签和剩下的海盐糖，纸星瓶真的不见了。她咬着嘴唇，说那里面有我们折了好久的星星。</p><p>林小满凑过来说，别急别急，我有老板姐姐留的联系方式，我帮你问。她拍着胸口，说包在我身上。她掏出那张写着短句的纸条，笑得像个小侠客。</p><p>车来了，江苒望着小店的方向，还是不肯上车。我轻轻碰了碰她的手，说下次来拿，还会多一瓶薄荷水。</p><p>她点头，跟着我上车，靠着窗不说话。铃铛安静了很久。</p><p>车开出县城的时候，我看见河面最后一点光也沉下去了。林小满在前排低头摆弄那张联系纸条，嘴里念念有词。顾远问她念什么，她说在想要怎么开口，才显得不着急，又让人记得把瓶子收好。</p><p>我看着窗外，心里忽然有点不安。纸星星丢了是小事，可江苒刚才的眼神，像是丢了很重要的东西。而小店姐姐那个本子里，除了我们的纸条，好像还夹着一张对折的纸条，上面的字迹，被磨得只剩一半。</p>',52)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
